import { readFile, writeFile } from "node:fs/promises";
import http from "node:http";
import https from "node:https";
import { fileURLToPath } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));

const DEFAULT_FILE = "postToAnglaisFacile.txt";
const DEFAULT_QUESTION =
  "* the skin of Englishmen is pale, the skin of an African is like chocolate.";

function option(name, fallback) {
  const hit = process.argv.find((a) => a.startsWith(`--${name}=`));
  return hit === undefined ? fallback : hit.slice(name.length + 3);
}

const has = (name) => process.argv.includes(`--${name}`);

function readStringLiteral(code, start) {
  const quote = code[start];
  if (quote !== '"' && quote !== "'") return null;
  let out = "";
  let i = start + 1;
  while (i < code.length) {
    const ch = code[i];
    if (ch === "\\") {
      const next = code[i + 1];
      const map = {
        n: "\n", t: "\t", r: "\r", b: "\b", f: "\f",
        '"': '"', "'": "'", "\\": "\\", "/": "/",
      };
      if (next === "u") {
        out += String.fromCharCode(parseInt(code.slice(i + 2, i + 6), 16));
        i += 6;
        continue;
      }
      out += next in map ? map[next] : next;
      i += 2;
      continue;
    }
    if (ch === quote) return { value: out, end: i + 1 };
    out += ch;
    i += 1;
  }
  throw new Error("Unterminated string literal found.");
}

function readObjectLiteral(code, start) {
  if (code[start] !== "{") return null;
  let depth = 0;
  let i = start;
  while (i < code.length) {
    const ch = code[i];
    if (ch === '"' || ch === "'") {
      i = readStringLiteral(code, i).end;
      continue;
    }
    if (ch === "{") depth += 1;
    else if (ch === "}") {
      depth -= 1;
      if (depth === 0) return { raw: code.slice(start, i + 1), end: i + 1 };
    }
    i += 1;
  }
  throw new Error("Unterminated object literal found.");
}

function parseRequest(code) {
  const urlMatch = /fetch\s*\(\s*(['"])/.exec(code);
  if (!urlMatch) throw new Error('No fetch("... found in the file.');
  const url = readStringLiteral(code, urlMatch.index + urlMatch[0].length - 1).value;

  const headersKey = /(['"]?)headers\1\s*:\s*/.exec(code);
  if (!headersKey) throw new Error('No "headers" object found in the file.');
  const headersObj = readObjectLiteral(code, headersKey.index + headersKey[0].length);
  const headers = JSON.parse(headersObj.raw);

  const bodyKey = /(['"]?)body\1\s*:\s*/.exec(code);
  if (!bodyKey) throw new Error('No "body" field found in the file.');
  const bodyStart = bodyKey.index + bodyKey[0].length;
  const bodyLit = readStringLiteral(code, bodyStart);
  if (!bodyLit) {
    throw new Error('The "body" is not a string. Copy the request as "fetch" (not as HAR/curl).');
  }

  const methodMatch = /(['"]?)method\1\s*:\s*(['"])([A-Za-z]+)\2/.exec(code);

  return { url, headers, body: bodyLit.value, method: methodMatch ? methodMatch[3] : "POST" };
}

function encodeField(text) {
  return encodeURIComponent(text).replace(/%20/g, "+");
}

function buildRequestBody(body, newQuestion, answer) {
  let old = null;
  let next = null;
  let foundQ1 = false;
  let foundR1 = false;

  const parts = body.split("&").map((part) => {
    const eq = part.indexOf("=");
    if (eq === -1) return part;
    const key = part.slice(0, eq);
    const rawValue = part.slice(eq + 1);

    if (key === "q1") {
      foundQ1 = true;
      old = decodeURIComponent(rawValue.replace(/\+/g, " "));
      const image = /^\{[^}]*\}/.exec(old);
      next = (image ? `${image[0]} ` : "") + newQuestion.trim();
      return `${key}=${encodeField(next)}`;
    }

    if (key === "r1" && answer !== null) {
      foundR1 = true;
      return `${key}=${encodeField(answer)}`;
    }

    return part;
  });

  if (!foundQ1) throw new Error("No field q1 in the request body.");
  if (answer !== null && !foundR1) throw new Error("No field r1 in the request body.");

  return { old, next, encoded: parts.join("&") };
}

function send(urlString, { method, headers, body }) {
  const target = new URL(urlString);
  const payload = Buffer.from(body, "utf8");
  const requestHeaders = {};

  for (const [key, value] of Object.entries(headers)) {
    const lower = key.toLowerCase();
    if (lower.startsWith(":") || lower === "host" || lower === "content-length") continue;
    if (lower === "content-encoding" || lower === "transfer-encoding") continue;
    requestHeaders[key] = value;
  }
  requestHeaders["Content-Length"] = payload.length;

  const agent = target.protocol === "https:" ? https : http;

  return new Promise((resolve, reject) => {
    const req = agent.request(
      target,
      { method, headers: requestHeaders },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    req.on("error", reject);
    req.end(payload);
  });
}

function writeRequestFile(file, { url, method, headers, body }) {
  const cookie = headers.cookie ? "\n    \"cookie\": \"<hidden>\"" : "";
  const lines = [
    `fetch(${JSON.stringify(url)}, {`,
    "  \"headers\": {",
    `    \"accept\": ${JSON.stringify(headers.accept ?? "*/*")},${cookie}`,
    `    \"content-type\": ${JSON.stringify(headers["content-type"] ?? "application/x-www-form-urlencoded")}`,
    "  },",
    `  \"body\": ${JSON.stringify(body)},`,
    `  \"method\": ${JSON.stringify(method)}`,
    "});",
    "",
  ];
  return writeFile(file, lines.join("\n"), "utf8");
}

const file = path.resolve(here, option("file", DEFAULT_FILE));
const question = option("question", DEFAULT_QUESTION);
const answer = option("answer", null);
const dry = has("dry");
const save = has("save");

try {
  const code = await readFile(file, "utf8");
  if (code.trim() === "") {
    console.error(
      `${path.basename(file)} is empty.\n` +
        "Open the edit page of the test in Chrome, DevTools > Network > right click the POST request\n" +
        '> Copy > Copy as fetch, and paste the code into that file.',
    );
    process.exit(1);
  }

  const request = parseRequest(code);
  const { old, next, encoded } = buildRequestBody(request.body, question, answer);

  console.log("q1 before:", old);
  console.log("q1 after :", next);
  if (answer !== null) console.log("r1 after :", answer);
  console.log("target   :", request.method, request.url);

  if (save) {
    const copy = path.join(here, `${path.basename(file, path.extname(file))}.updated.txt`);
    await writeRequestFile(copy, { ...request, body: encoded });
    console.log("saved    :", path.basename(copy));
  }

  if (dry) {
    console.log("\n--dry: nothing was sent. New body:\n");
    console.log(encoded);
    process.exit(0);
  }

  const response = await send(request.url, { ...request, body: encoded });
  console.log("status   :", response.status, response.statusMessage ?? "");

  const text = response.body ?? "";
  console.log("response :", text.replace(/\s+/g, " ").slice(0, 400) || "(empty)");

  if (response.status >= 400) process.exit(1);
} catch (error) {
  console.error("Error:", error instanceof Error ? error.message : error);
  process.exit(1);
}

