interface FrageAntwort { q: string; r: string; }

function zuFrageAntwort(ex: Exercise): FrageAntwort | null {
  const bild = ex.imageUrl ? `<img href="${absoluteUrl(ex.imageUrl)}"></img>` : "";
  if (ex.type === "multipleChoice") {
    const richtig = (ex.options ?? []).filter(o => o.correct).map(o => o.option);
    const alle = (ex.options ?? []).map(o => o.option);
    // richtige Antwort zuerst, damit sie auf francaisfacile die erste Option ist
    const sortiert = [...richtig, ...alle.filter(o => !richtig.includes(o))];
    const q = (ex.question ?? ex.gapText ?? "").replace(/_+/g, "*").replace(/\{[^{}]*\}/g, "*");
    return { q: (bild ? bild : "") + q, r: sortiert.join("|") };
