import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync(process.argv[2] ?? "C:/Users/imelf/.local/share/opencode/opencode.db", { readOnly: true });

const rows = db.prepare("SELECT name, type FROM sqlite_master WHERE type IN ('table','view') ORDER BY name").all();
for (const r of rows) {
  console.log("### " + r.type + " " + r.name);
  const cols = db.prepare(`PRAGMA table_info(${JSON.stringify(r.name)})`).all();
  console.log("    " + cols.map((c) => `${c.name}:${c.type}`).join(", "));
}

import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync("C:/Users/imelf/.local/share/opencode/opencode.db", { readOnly: true });

const rows = db
  .prepare("SELECT id, directory, title, version, agent, time_created, time_updated, parent_id FROM session ORDER BY time_updated DESC LIMIT 15")
  .all();

for (const r of rows) {
  const n = db.prepare("SELECT COUNT(*) AS c FROM message WHERE session_id = ?").get(r.id);
  console.log(
    [new Date(r.time_created).toISOString(), r.id, "msgs=" + n.c, r.directory, JSON.stringify(r.title), "parent=" + (r.parent_id ?? "-")].join("  "),
  );
}

import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync("C:/Users/imelf/.local/share/opencode/opencode.db", { readOnly: true });
const sid = process.argv[2];

const msgs = db.prepare("SELECT id, time_created, data FROM message WHERE session_id = ? ORDER BY time_created").all(sid);
for (const m of msgs.slice(0, 6)) {
  console.log("=== MESSAGE " + m.id + " " + new Date(m.time_created).toISOString());
  console.log(JSON.stringify(JSON.parse(m.data), null, 1).slice(0, 1200));
  const parts = db.prepare("SELECT id, data FROM part WHERE message_id = ? ORDER BY time_created").all(m.id);
  for (const p of parts.slice(0, 4)) {
    console.log("  --- PART " + p.id);
    console.log("  " + JSON.stringify(JSON.parse(p.data), null, 1).slice(0, 1500).split("\n").join("\n  "));
  }
}

import { DatabaseSync } from "node:sqlite";
import { spawnSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import path from "node:path";

const db = new DatabaseSync("C:/Users/imelf/.local/share/opencode/opencode.db", { readOnly: true });

const dir = process.cwd();
const row = db
  .prepare(
    "SELECT id, title, time_created, time_updated, parent_id FROM session WHERE directory = ? AND parent_id IS NULL ORDER BY time_updated DESC LIMIT 1",
  )
  .get(dir);

if (!row) {
  console.error("no session found for " + dir);
  process.exit(1);
}

console.log("session :", row.id);
console.log("title   :", row.title);

const exe = "C:/Users/imelf/AppData/Roaming/npm/opencode.cmd";
const res = spawnSync(exe, ["export", row.id], { encoding: "utf8", maxBuffer: 1024 * 1024 * 256, shell: true });

if (res.status !== 0) {
  console.error("export failed:", res.stderr);
  process.exit(1);
}

const json = res.stdout;
JSON.parse(json); // throws if it is not valid JSON

const day = new Date(row.time_created).toISOString().slice(0, 10);
const ziel = path.join(dir, `chat-${day}.json`);
writeFileSync(ziel, json, "utf8");
console.log("written :", ziel, (json.length / 1024).toFixed(0) + " kB");

