import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const quelle = process.argv[2];
const ziel = process.argv[3];

const json = JSON.parse(readFileSync(quelle, "utf8"));
const info = json.info ?? {};
const messages = json.messages ?? [];

const zeit = (ms) => new Date(ms).toISOString().replace("T", " ").slice(0, 16);
const aus = [];

aus.push("# Chat-Protokoll (opencode)");
aus.push("");
aus.push(`- **Titel:** ${info.title ?? ""}`);
aus.push(`- **Session-ID:** \`${info.id ?? ""}\``);
aus.push(`- **Verzeichnis:** \`${info.directory ?? ""}\``);
aus.push(`- **Erstellt:** ${zeit(info.time?.created ?? Date.now())} UTC`);
aus.push(`- **Quelle:** \`${path.basename(quelle)}\` (vollständig, maschinenlesbar)`);
aus.push("");
aus.push("## Wieder öffnen");
aus.push("");
aus.push("```bash");
aus.push("# Diese Session einfach fortsetzen (sie liegt schon lokal in opencode):");
aus.push(`opencode -s ${info.id ?? "<sessionID>"}`);
aus.push("");
aus.push("# Aus der JSON-Datei importieren, falls die Datenbank weg ist:");
aus.push(`opencode import ${path.basename(quelle)}`);
aus.push("");
aus.push("# Letzte Session des Verzeichnisses fortsetzen:");
aus.push("opencode -c");
aus.push("```");
aus.push("");
aus.push("---");
aus.push("");

for (const m of messages) {
  const role = m.info?.role;
  if (role !== "user" && role !== "assistant") continue;

  const texte = (m.parts ?? [])
    .filter((p) => p.type === "text" && (p.text ?? "").trim())
    .map((p) => p.text.trim());
  const werkzeuge = (m.parts ?? [])
    .filter((p) => p.type === "tool")
    .map((p) => {
      const status = p.state?.status ?? "?";
      const marke = status === "error" ? "!" : status === "completed" ? "✓" : "…";
      return `${marke} ${p.tool}`;
    });

  if (texte.length === 0 && werkzeuge.length === 0) continue;

  aus.push(`## ${role === "user" ? "User" : "Assistant"} — ${zeit(m.info?.time?.created ?? 0)} UTC`);
  aus.push("");

  if (rolle_toolsummary(werkzeuge)) aus.push("");

  for (const t of texte) aus.push(t, "");

  if (werkzeuge.length > 0) {
    aus.push(`> Werkzeuge: ${werkzeuge.join(", ")}`, "");
  }
}

function rolle_toolsummary() {
  return false;
}

writeFileSync(ziel, aus.join("\n"), "utf8");
console.log("written:", ziel);

